import{_ as t,o as a,c as i,am as l}from"./chunks/framework._FJXuPhs.js";const m=JSON.parse('{"title":"系统设计_数据安全","description":"","frontmatter":{"title":"系统设计_数据安全","excerpt":"系统设计_数据安全","date":"2024-03-22 22:27:43","updated":"2024-03-22 22:27:43"},"headers":[],"relativePath":"架构篇/系统设计_数据安全/index.md","filePath":"架构篇/系统设计_数据安全/index.md","lastUpdated":null}'),n={name:"架构篇/系统设计_数据安全/index.md"};function r(s,e,o,p,_,d){return a(),i("div",null,[...e[0]||(e[0]=[l('<h3 id="_1、常用加密算法" tabindex="-1">1、常用加密算法 <a class="header-anchor" href="#_1、常用加密算法" aria-label="Permalink to &quot;1、常用加密算法&quot;">​</a></h3><p>加密算法是一种用数学方法对数据进行变换的技术，目的是保护数据的安全，防止被未经授权的人读取或修改。加密算法可以分为三大类：对称加密算法、非对称加密算法和哈希算法（也叫摘要算法）。</p><p>日常开发中常见的需要用到的加密算法的场景：</p><ol><li>保存在数据库中的密码需要加盐之后使用哈希算法（比如 BCrypt）进行加密。</li><li>保存在数据库中的银行卡号、身份号这类敏感数据需要使用对称加密算法（比如 AES）保存。</li><li>网络传输的敏感数据比如银行卡号、身份号需要用 HTTPS + 非对称加密算法（如 RSA）来保证传输数据的安全性。</li><li>……</li></ol><p>参考： <a href="https://javaguide.cn/system-design/security/encryption-algorithms.html" target="_blank" rel="noreferrer">https://javaguide.cn/system-design/security/encryption-algorithms.html</a></p><ul><li>哈希算法</li><li>对称算法</li><li>非对称算法</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20240322225241.png" alt="image.png"></p>',7)])])}const u=t(n,[["render",r]]);export{m as __pageData,u as default};
